package com.locallaunch.service;
import com.locallaunch.dto.BusinessUpdateRequest; import com.locallaunch.entity.*; import com.locallaunch.exception.ResourceNotFoundException; import com.locallaunch.repository.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import java.util.List;
@Service public class BusinessUpdateService { private final BusinessUpdateRepository repo; private final BusinessRepository businessRepo; private final UserRepository userRepo; public BusinessUpdateService(BusinessUpdateRepository r,BusinessRepository b,UserRepository u){repo=r;businessRepo=b;userRepo=u;} private User user(){String email=SecurityContextHolder.getContext().getAuthentication().getName();return userRepo.findByEmail(email).orElseThrow(()->new ResourceNotFoundException("User not found"));} public BusinessUpdate add(Long businessId,BusinessUpdateRequest req){Business b=businessRepo.findByIdAndOwnerId(businessId,user().getId()).orElseThrow(()->new ResourceNotFoundException("Business not found or access denied"));BusinessUpdate u=new BusinessUpdate();u.setBusiness(b);u.setTitle(req.getTitle());u.setContent(req.getContent());u.setImageUrl(req.getImageUrl());return repo.save(u);} public List<BusinessUpdate> list(Long businessId){businessRepo.findByIdAndOwnerId(businessId,user().getId()).orElseThrow(()->new ResourceNotFoundException("Business not found or access denied"));return repo.findByBusinessIdOrderByCreatedAtDesc(businessId);} public void delete(Long id){BusinessUpdate u=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Update not found")); if(!u.getBusiness().getOwner().getId().equals(user().getId())) throw new ResourceNotFoundException("Update not found or access denied");repo.delete(u);} }
